package io.nebulaflow.rag;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="rag_chunks",indexes={@Index(name="idx_rag_scope",columnList="tenant_id,collection_name")},uniqueConstraints=@UniqueConstraint(name="uk_rag_position",columnNames={"tenant_id","collection_name","document_id","chunk_index"}))
public class RagChunkEntity { @Id private UUID id; @Column(name="tenant_id",nullable=false,length=120) private String tenantId; @Column(name="collection_name",nullable=false,length=160) private String collectionName; @Column(name="document_id",nullable=false,length=200) private String documentId; @Column(name="chunk_index",nullable=false) private int chunkIndex; @Column(nullable=false,columnDefinition="text") private String content; @Column(name="metadata_json",nullable=false,columnDefinition="text") private String metadataJson; @Column(name="embedding_json",nullable=false,columnDefinition="text") private String embeddingJson; @Column(name="created_at",nullable=false) private Instant createdAt; protected RagChunkEntity(){}
 public RagChunkEntity(UUID id,String tenantId,String collectionName,String documentId,int chunkIndex,String content,String metadataJson,String embeddingJson,Instant createdAt){this.id=id;this.tenantId=tenantId;this.collectionName=collectionName;this.documentId=documentId;this.chunkIndex=chunkIndex;this.content=content;this.metadataJson=metadataJson;this.embeddingJson=embeddingJson;this.createdAt=createdAt;}
 public String getDocumentId(){return documentId;} public int getChunkIndex(){return chunkIndex;} public String getContent(){return content;} public String getMetadataJson(){return metadataJson;} public String getEmbeddingJson(){return embeddingJson;}
}